DECLARE
  got_lines  text := (SELECT md5(coalesce(string_agg(concat_ws(chr(31), coalesce(id::text, ''), coalesce(parent_id::text, ''), coalesce(statement::text, ''), coalesce(sort_order::text, ''), coalesce(line_type::text, ''), coalesce(indent::text, ''), coalesce(label_id::text, ''), coalesce(label_en::text, ''), coalesce(notes_ref::text, ''), coalesce(value_cy::text, ''), coalesce(value_py::text, ''), coalesce(computed_cy::text, ''), coalesce(computed_py::text, ''), coalesce(source_page::text, ''), coalesce(line_key::text, ''), coalesce(fsli_slug::text, ''), coalesce(printed_diff_cy::text, ''), coalesce(printed_diff_py::text, ''), coalesce(printed_diff_note::text, '')), chr(30) ORDER BY statement COLLATE "C", sort_order), ''))
     FROM public.fs_line WHERE period_id = md5('https://dikagustiana.com/fs/phe/fy2024')::uuid);
  got_cells  text := (SELECT md5(coalesce(string_agg(concat_ws(chr(31), coalesce(row_key::text, ''), coalesce(col_key::text, ''), coalesce(row_label_id::text, ''), coalesce(row_label_en::text, ''), coalesce(row_order::text, ''), coalesce(col_label_id::text, ''), coalesce(col_label_en::text, ''), coalesce(col_order::text, ''), coalesce(value::text, ''), coalesce(source_page::text, ''), coalesce(notes_ref::text, '')), chr(30) ORDER BY row_order, col_order), ''))
     FROM public.fs_soce_cell WHERE period_id = md5('https://dikagustiana.com/fs/phe/fy2024')::uuid);
  got_checks text := (SELECT md5(coalesce(string_agg(concat_ws(chr(31), coalesce(rule_id::text, ''), coalesce(statement::text, ''), coalesce(description::text, ''), coalesce(expected::text, ''), coalesce(actual::text, ''), coalesce(diff::text, ''), coalesce(passed::text, '')), chr(30) ORDER BY rule_id COLLATE "C"), ''))
     FROM public.fs_check WHERE period_id = md5('https://dikagustiana.com/fs/phe/fy2024')::uuid);
BEGIN
  IF got_lines <> '790537976fb1e2621f916797cb4607c1' THEN
    RAISE EXCEPTION 'fs_line differs from statements.json (md5 %, expected 790537976fb1e2621f916797cb4607c1)', got_lines;
  END IF;
  IF got_cells <> '896b823edc59711b2622c577f4f89acb' THEN
    RAISE EXCEPTION 'fs_soce_cell differs from statements.json (md5 %, expected 896b823edc59711b2622c577f4f89acb)', got_cells;
  END IF;
  IF got_checks <> 'fa0479684ad04c1992b740090a7a78da' THEN
    RAISE EXCEPTION 'fs_check differs from checks.json (md5 %, expected fa0479684ad04c1992b740090a7a78da)', got_checks;
  END IF;
END
$verify$;
